+/// check belongs to both.
+pub(super) fn validate(p: &Finish3DParams, facets: &[Triangle]) -> Result<(), GenError> {
+    if !(p.tool_diameter.is_finite()
+        && p.tool_diameter > 0.0
+        && p.tolerance.is_finite()
+        && p.tolerance > 0.0
